// n8n Code node — Language: JavaScript — Mode: Run Once for All Items

// ==================== CONFIG (easily tweak here) ====================
const PRIORITY_ORDER = { Critical: 0, Failed: 1, Opportunity: 2 };
const BUG_STATUSES = Object.keys(PRIORITY_ORDER);

// Points awarded per error, based on QA Status
const SEVERITY_POINTS = {
  Opportunity: 2,
  Failed: 5,
  Critical: 10,
};

// Multiplier applied to an error's points based on how many times
// that same case number has appeared (i.e. follow-up count)
const FOLLOW_UP_MULTIPLIER = {
  0: 1, // no changes to points per error
  1: 2, // x2
  2: 5, // x5
};
// Anything above 2 follow-ups reuses the highest defined multiplier.
const MAX_FOLLOW_UP_KEY = Math.max(...Object.keys(FOLLOW_UP_MULTIPLIER).map(Number));

// ==================== TODO: FILL THIS IN MANUALLY ====================
// One entry per user. `name` must match transformName()'s output exactly
// (Title Case, e.g. "Dylan Jitton") since that's the only identity string
// available from the sheet data.
const USER_DIRECTORY = [
  { name: "Dylan Jitton", slack_id: "U0A0APJCK88", number: 65999081 },
  { name: "Nicole Gongora", slack_id: "U074YJZ5F7A", number: 68141001},
  { name: "Kattya Torrez", slack_id: "U0A1FN25GV6", number: 65999081},
  { name: "Diego Torrez", slack_id: "U093PVCG78C", number: 65999081},
  { name: "Nestor Apaza", slack_id: "U0A12TP39EC", number: 65999081},
  { name: "Edmundo Morales", slack_id: "U03S0B4JV2S", number: 65999081},
  { name: "Gustavo Pillco", slack_id: "U088MKHQQ90", number: 73234444},
  { name: "Diego Delgadillo", slack_id: "U074WQJ990U", number: 65999081},
  { name: "Orietha Castillo", slack_id: "U0AHAMMLJ6L", number: 65999081},
  { name: "Diego Chavez", slack_id: "U0420BRRH26", number: 65999081},
];

// Build a quick lookup map keyed by name, so we don't loop the array per user.
const USER_DIRECTORY_MAP = Object.fromEntries(
  USER_DIRECTORY.map((u) => [u.name, u])
);
// =======================================================================

// "romel.pinto@coxautoinc.com" -> "Romel Pinto"
function transformName(rawName) {
  if (!rawName) return 'Unknown';
  const localPart = String(rawName).split('@')[0];
  return localPart
    .split('.')
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1).toLowerCase())
    .join(' ');
}

const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && Object.keys(r).length > 0);

// Count how many times each case number appears among bug rows,
// to derive a follow_up count per error (0 = first occurrence).
const caseOccurrenceCount = {};
for (const row of rows) {
  const status = row['QA Status'];
  if (!BUG_STATUSES.includes(status)) continue;
  const caseId = row['ID / Task / Case Number'] || '';
  caseOccurrenceCount[caseId] = (caseOccurrenceCount[caseId] || 0) + 1;
}

const grouped = {};
for (const row of rows) {
  const status = row['QA Status'];
  if (!BUG_STATUSES.includes(status)) continue;

  const email = String(row['Name'] || '').trim();
  const userKey = transformName(email);

  if (!grouped[userKey]) {
    grouped[userKey] = { user: userKey, email, errors: [] };
  }

  const qaComment = (row['QA Comment'] || '').toString().trim();
  const qaFixComment = (row['QA Fix Comment'] || '').toString().trim();
  const caseId = row['ID / Task / Case Number'] || '';

  const occurrences = caseOccurrenceCount[caseId] || 1;
  const followUp = Math.min(occurrences - 1, MAX_FOLLOW_UP_KEY);

  grouped[userKey].errors.push({
    'QA Status': status,
    'ID / Task / Case Number': caseId,
    'QA Comment': qaComment || null,
    'QA Fix Comment': qaFixComment || null,
    followUp,
  });
}

for (const obj of Object.values(grouped)) {
  obj.errors.sort(
    (a, b) => PRIORITY_ORDER[a['QA Status']] - PRIORITY_ORDER[b['QA Status']],
  );
}

const out = [];
for (const obj of Object.values(grouped)) {
  let severityLevel = 0;

  const errors = obj.errors.map((err) => {
    const basePoints = SEVERITY_POINTS[err['QA Status']] || 0;
    const multiplier = FOLLOW_UP_MULTIPLIER[err.followUp] ?? FOLLOW_UP_MULTIPLIER[MAX_FOLLOW_UP_KEY];
    const points = basePoints * multiplier;
    severityLevel += points;

    return {
      id: err['ID / Task / Case Number'],
      status: err['QA Status'].toUpperCase(),
      follow_up: err.followUp,
      error_message: err['QA Comment'] || 'N/A',
      fixed: !!err['QA Fix Comment'],
    };
  });

  const directoryEntry = USER_DIRECTORY_MAP[obj.user];

  out.push({
    json: {
      name: obj.user,
      slack_id: directoryEntry?.slack_id || 'TODO_ADD_SLACK_ID',
      phone_number: directoryEntry?.number ?? null,
      errors_found: errors.length,
      error_severity_level: severityLevel,
      errors,
    },
  });
}
return out
//return [{json:{out}}];

values.content:
=Generate a Message for a bug report, like writing a brief letter to reach out to a developer according to the severity of the errors:
this is the dev's Name: {{ $json.name }}
this is the Error Severity Level (ESL):  {{ $json.error_severity_level }}
if the ESL is lower than 10, then generate a semi-friendly message asking to fix the errors "no rush, fix them whenever you have time for it".
if the ESL is bigger than 10, but lower than 20, then write the message in a middle ground tone, asking to "please, do not let these errors pass for too long, please find some time to fix them"
and if the ESL is higher than 20, then write the message in a serious and urgency-demanding tone, like "you have {{ $json.errors_found }} errors pending to solve, please fix them inmediatly"
then list and summarize these errors:{{ $json.errors.map(item => `[${item['status']}] Error Message: ${item['error_message']}`).join('\n') }}
and end the message with a thanks, have a great day

