// n8n Code node — Language: JavaScript — Mode: Run Once for All Items

// Add/remove statuses to exclude here — normalized comparison below
// handles casing and extra whitespace automatically.
const EXCLUDED_STATUSES = ['Passed', 'In Progress'];

function normalize(str) {
  return String(str || '').trim().toLowerCase();
}

const normalizedExcluded = EXCLUDED_STATUSES.map(normalize);

const rows = $input.all().map((item) => item.json);
const total_cases=rows.length;
const filtered = [];
for (const row of rows) {
  const status = row['QA Status'];
  const completed_by=row['QA Completed by:'];

  if (normalizedExcluded.includes(normalize(status))) continue;

  filtered.push({
    'QA Completed by':completed_by,
    'QA Status': status,
    'QA Comment': (row['QA Comment'] || '').toString().trim() || null,
  });
}
const out = filtered.map((entry) => ({ json: entry }));
return {"json":{total_cases,out}}

// Severity tiers, mirroring the downstream Switch node's routing rules.
function getCategory(severityLevel) {
  if (severityLevel < 10) return 'light';
  if (severityLevel <= 20) return 'medium';
  return 'alert';
}

// Loop over input items and tag each one with its own category
for (const item of $input.all()) {
  item.json.category = getCategory(item.json.error_severity_level);
}

return $input.all();

